sys_variable_value.value:
(function execute(inputs, outputs) {
	try {

		var certificate = new global.GlideQuery("sn_disco_certmgmt_renew_task")
			.where("sys_id", inputs.task.sys_id)
			.selectOne("subject_common_name", "certificate")
			.orElse(null);

		if (!certificate) {
			throw "EDX Dispara Job Ansible - certificado não consta da task " + inputs.task.number;
		}

		var installedGq = new global.GlideQuery("sn_disco_certmgmt_cmdb_installed_certificate")
			.where("certificate", certificate.certificate)
			.where("port", "IN", [443, 8443, 9443])
			.orderBy("port")
			.limit(1)
			.selectOne("port", "source")
			.orElse({ port: null });

		if (!installedGq.port) {
			throw "EDX Dispara Job Ansible: Certificate not installed on accessible port " + certificate.subject_common_name;
		}

		outputs.certificate_url = "https://" + certificate.subject_common_name + ":" + installedGq.port;
		outputs.job_template = "job_templates/15/launch";

	} catch (ex) {
		var errorInputs = {
			task_id: inputs.task,
			work_notes: ex
		};
		sn_fd.FlowAPI.getRunner().action('sn_disco_certmgmt.update_cert_task_work_notes').inBackground().withInputs(errorInputs).run();
		throw ex;
	}
})(inputs, outputs);

