sys_hub_input_scripts.script:
{"body":{"scriptActive":true,"script":"var body = {
	extra_vars: {
		url: fd_data._1__obtain_awx_job_template_url.certificate_url,
		change_order: "CHG12345678"
	}
}
var certificate = fd_data.action_inputs.task.certificate;

if(!certificate || !certificate.subject_common_name){
	throw "Missing certificate info in task " + fd_data.action_inputs.task.number;
}

var installedGq = new global.GlideQuery("sn_disco_certmgmt_cmdb_installed_certificate")
	.where("certificate", certificate)
	.where("port", "IN", [443, 8443, 9443])
	.orderBy("port")
	.limit(1)
	.selectOne("port", "source")
	.orElse({ port: null })
if (!installedGq.port) {
	throw "EDX Dispara Job Ansible: Certificate not installed on accessible port " + certificate.subject_common_name;
}

// EDX Carlos Paiva - Remover throw abaixo para amb. PROD
// Só permitido atualizar 1 URL em TESTE/DEV
if(certificate.subject_common_name != "autocert.capgv.intra.bnb"){
	throw('EDX - TESTE - só é permitida a URL autocert.capgv.intra.bnb em amb. DEV. Remover para PROD');
}	
body.extra_vars.url = "https://" + certificate.subject_common_name + ":" + installedGq.port;

return JSON.stringify(body);"}}

